      );
    };
    reject(env, { ...trustedOutputs, manifestSha256: hash("wrong") });
    reject(env, { ...trustedOutputs, archiveSha256: hash("wrong") });
    reject({ ...env, GITHUB_RUN_ATTEMPT: "3" });
    reject({ ...env, GITHUB_SHA: "f".repeat(40) }, trustedOutputs, /source/u);
    reject(
