text(await tools.exec_command({cmd:"cat > scripts/ci/linux-workspace.sh <<'EOF'
#!/usr/bin/env bash
# All compiler-cohort consumers independently derive the pinned coverage env.
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$root"
export CARGO_TARGET_DIR="$root/target/llvm-cov-target"
# Assignment preserves show-env failure; eval of a failed substitution does not.
coverage_environment="$(cargo llvm-cov show-env --sh)"
eval "$coverage_environment"
ulimit -c 262144
mode="${1:-}"
shift || exit 2
case "$mode" in
    produce) node scripts/ci/windows-coverage.mjs produce-linux-workspace "$@" ;;
    default) node scripts/ci/windows-coverage.mjs consume-linux-workspace "$@" ;;
    ignored) node scripts/evals/backend-runner.mjs --archive "$@" ;;
    *) echo 'Usage: linux-workspace.sh produce|default|ignored ARGS...' >&2; exit 2 ;;
esac
EOF
python3 - <<'PY'
p='scripts/ci/windows-coverage.mjs';s=open(p).read().replace('  if (!profile.instrumented)\n    writeJson(\n      path.join(directory, "feature-resolution.json"),','  if (profile.name !== "windows")\n    writeJson(\n      path.join(directory, "feature-resolution.json"),',1)
s=s.replace('export async function collectMacRemaining(directory, outputs, trusted) {','''export async function collectMacRemaining(directory, outputs, trusted) {
  return collectDefaultArchive(directory, outputs, trusted);
}

export async function collectDefaultArchive(directory, outputs, trusted, { profile: profileName = "macos-remaining" } = {}) {
  const linux = profileName === "linux-workspace";
