test("Linux coverage environment failure cannot be masked by eval or admit execution", async (t) => {
  const root = mkdtempSync(path.join(tmpdir(), "mesh-linux-env-"));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  mkdirSync(path.join(root, "scripts/ci"), { recursive: true });
  mkdirSync(path.join(root, "bin"));
  const wrapper = path.join(root, "scripts/ci/linux-workspace.sh");
  copyFileSync(new URL("./linux-workspace.sh", import.meta.url), wrapper);
  writeFileSync(
    path.join(root, "bin/cargo"),
    '#!/usr/bin/env bash\nprintf "%s\\n" "export LLVM_PROFILE_FILE=invalid"\nexit 37\n',
    { mode: 0o755 },
  );
  writeFileSync(
    path.join(root, "bin/node"),
    '#!/usr/bin/env bash\ntouch "$MESH_ENV_EXECUTED"\n',
    { mode: 0o755 },
  );
  const marker = path.join(root, "executed");
  const result = spawnSync(
    "bash",
    [wrapper, "produce", path.join(root, "archive")],
    {
      env: {
        ...process.env,
        PATH: `${path.join(root, "bin")}:${process.env.PATH}`,
        MESH_ENV_EXECUTED: marker,
      },
      encoding: "utf8",
    },
  );
  assert.equal(result.status, 37);
  assert.equal(existsSync(marker), false);
});
#!/usr/bin/env bash
# All compiler-cohort consumers independently derive the pinned coverage env.
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$root"
export CARGO_TARGET_DIR="$root/target/llvm-cov-target"
# Assignment preserves show-env failure; eval of a failed substitution does not.
coverage_environment="$(cargo llvm-cov show-env --sh)"
eval "$coverage_environment"
ulimit -c 262144
mode="${1:-}"
shift || exit 2
case "$mode" in
    produce) node scripts/ci/windows-coverage.mjs produce-linux-workspace "$@" ;;
    default) node scripts/ci/windows-coverage.mjs consume-linux-workspace "$@" ;;
    ignored) node scripts/evals/backend-runner.mjs --archive "$@" ;;
    *) echo 'Usage: linux-workspace.sh produce|default|ignored ARGS...' >&2; exit 2 ;;
esac
  const step = (block, name) => block.split(/^      - /m).find(value => value.startsWith(`name: ${name}\n`));
  for (const [id, os, label, command] of [
    ["checks", "ubuntu-latest", "Linux", "linux --defer-report"],
    ["macos-native", "macos-latest", "macOS", "macos-host"],
  ]) {
    const block = job(id);
    assert.ok(block, id);
    assert.match(block, new RegExp(`runs-on: ${os}`, "u"));
    assert.match(block, /shell: bash/u);
    assert.doesNotMatch(block, /matrix:/u);
    const install = step(block, "Install cargo-llvm-cov and cargo-nextest");
    assert.match(install, /if: \$\{\{ steps\.scope\.outputs\.full == 'true' \}\}/u);
    assert.ok(install.includes(`cargo-llvm-cov@${versions.llvmCov},cargo-nextest@${versions.nextest}`));
    for (const [name, expected] of [["Clippy", "cargo clippy --workspace --all-targets -- -D warnings"], ["Build workspace", "cargo build --workspace --locked"]]) {
      const boundary = step(block, name);
      assert.ok(boundary.includes(expected));
      assert.match(boundary, /working-directory: src-tauri/u);
      assert.match(boundary, /if: \$\{\{ steps\.scope\.outputs\.full == 'true' \}\}/u);
      assert.ok(block.indexOf("name: Build frontend") < block.indexOf(`name: ${name}`));
    }
    if(id === "checks") {
      assert.match(step(block,"Produce sealed Linux workspace archive"),/linux-workspace.sh produce/u);
      assert.match(block,/cargo test --workspace --doc --locked/u);
      assert.doesNotMatch(block,/workspace-coverage.sh linux|name: Upload coverage to Codecov/u);
      continue;
    }
    const pass = step(block, `Test + coverage (${label})`);
    assert.match(pass, /working-directory: src-tauri/u);
    assert.match(pass, /shell: bash/u);
    assert.ok(pass.includes(`bash ../scripts/ci/workspace-coverage.sh ${command}`));
    assert.doesNotMatch(pass, /run_coverage|cargo llvm-cov/u);
    assert.deepEqual([...block.matchAll(/cargo test --workspace([^\n]*)/gu)].map(match => match[1].trim()), [id === "checks" ? "--doc --locked" : "--doc"], "preserve separate doctests without repeating default targets");
    if (id === "macos-native") assert.match(pass, /RUST_TEST_THREADS: 4\n          NEXTEST_TEST_THREADS: 4/u);
