    finally { clearTimeout(timer); }
  };
  const running = () => {
    if (!escaped) return false;
    const state = spawnSync("ps", ["-o", "stat=", "-p", String(escaped)], { encoding: "utf8" }).stdout.trim();
    return !!state && !state.startsWith("Z");
