async fn linked_device_catches_up_incoming_dm_after_reconnect() {
    use crate::identity::account::Account;
    use crate::node::test_support::IndependentPeerRuntime;
    use futures_util::FutureExt;

    let fixture_started = std::time::Instant::now();
    let phase = |name: &'static str| {
        eprintln!(
            "linked reconnect phase={name} elapsed_ms={}",
            fixture_started.elapsed().as_millis()
        );
    };
    phase("setup_begin");

    let a1 = DeviceIdentity::generate();
    let a2 = DeviceIdentity::generate();
    let alice_account = Account::generate();
    let bob = DeviceIdentity::generate();
    let bob_account = Account::generate();
    let dir = tempfile::tempdir().unwrap();
    // Each simulated device needs its own private sidecars and media key.
    let a1_store = dir.path().join("a1");
    let a2_store = dir.path().join("a2");
    let bob_store = dir.path().join("bob");
    for store in [&a1_store, &a2_store, &bob_store] {
        std::fs::create_dir_all(store).unwrap();
    }

    let a1_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let a1_port = a1_listener.local_addr().unwrap().port();
    let a2_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let a2_port = a2_listener.local_addr().unwrap().port();
    let bob_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let bob_port = bob_listener.local_addr().unwrap().port();

    let a1_roster = Arc::new(Mutex::new(Roster::default()));
    add_account_peer(
        &a1_roster,
        &a2,
        &alice_account,
        "A2",
        a2_port,
        &a1.public().user_id(),
    );
    add_account_peer(
        &a1_roster,
        &bob,
        &bob_account,
        "Bob",
        bob_port,
        &a1.public().user_id(),
    );
    let a2_roster = Arc::new(Mutex::new(Roster::default()));
    add_account_peer(
                    .enumerate()
                    .filter_map(|(index, token)| {
                        (index == 0
                            || [
                                "outcome=",
                                "domain=",
                                "retry_ms=",
                                "pending=",
                                "after=",
                                "deferred=",
                                "reused=",
                                "priority=",
                                "failed=",
                            ]
                            .iter()
                            .any(|prefix| token.starts_with(prefix)))
                        .then_some(token)
                    })
                    .collect::<Vec<_>>()
                    .join(" ");
                let mut trace = trace.lock().unwrap();
                if trace.len() == 128 {
                    trace.pop_front();
                    omitted.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                }
                trace.push_back((
                    delivery_trace_started.elapsed().as_millis(),
                    label,
                    safe_phase,
                ));
            }));
    }
    phase("new_channel_send_begin");
    a1_node
        .send_channel_message(channel, b"after sibling joined")
        .await
        .unwrap();
    phase("new_channel_send_finished_source_history_begin");
    let original_new = channel_texts(&a1_node)
        .unwrap()
        .into_iter()
        .find(|row| row.text == b"after sibling joined")
        .unwrap()
        .id;
    phase("source_history_finished_delivery_observation_begin");
    let mut first_public_arrival = None;
    let new_delivery_deadline = tokio::time::Instant::now() + Duration::from_secs(15);
    let new_channel_delivery = tokio::time::timeout_at(new_delivery_deadline, async {
        loop {
            if first_public_arrival.is_none()
                && a2_node
                    .log
