//! Fixed send-time deadlines, clock policy and local erasure on both sides.

use super::{DmEnvelope, Node, NodeError};
use crate::eventlog::event::EventId;

/// Deadline authenticated inside either an account envelope or direct plaintext.
pub(in crate::node) fn plaintext_deadline(wire: &[u8]) -> Option<u64> {
    DmEnvelope::decode(wire).map_or_else(
        || crate::expiry::deadline(wire),
        |envelope| crate::expiry::deadline(&envelope.body),
    )
}

/// Sender-selected UTC deadline must still be in the future at acceptance.
pub(crate) fn validate_outgoing(deadline: Option<u64>) -> Result<(), NodeError> {
    if let Some(deadline) = deadline {
        let now = super::node::now_millis();
        if deadline <= now {
            return Err(NodeError::InvalidInput("expiration time has passed".into()));
        }
        if deadline > now.saturating_add(30 * 24 * 60 * 60 * 1000) {
            return Err(NodeError::InvalidInput(
                "expiration time is too far away".into(),
            ));
        }
    }
    Ok(())
}

impl Node {
    /// A backward clock change cannot make an observed message live forever.
    pub(in crate::node) fn recipient_expired(
        &self,
        wire: &[u8],
        id: EventId,
        sent_at_ms: u64,
    ) -> bool {
        let Some(deadline) = crate::expiry::deadline(wire) else {
            return false;
        };
        self.recipient_metadata_expired(deadline, id, sent_at_ms)
    }
    pub(in crate::node) fn recipient_metadata_expired(
        &self,
        deadline: u64,
        id: EventId,
        sent_at_ms: u64,
    ) -> bool {
        if deadline <= self.expiry_now() {
            return true;
        }
        let lifetime = deadline
            .saturating_sub(sent_at_ms)
            .min(30 * 24 * 60 * 60 * 1000);
        let mut seen = self
            .expiry_first_seen
            .lock()
            .expect("expiry mutex not poisoned");
        seen.entry(id)
            .or_insert_with(std::time::Instant::now)
            .elapsed()
            >= std::time::Duration::from_millis(lifetime)
    }
    pub(in crate::node) fn expired_received_file(
        &self,
        file_conv: crate::eventlog::event::ConversationId,
    ) -> Result<bool, crate::eventlog::LogError> {
        let files = self.received_files.lock().expect("files mutex");
        let mut after = None;
        loop {
            let page = files.file_headers(
                &file_conv,
                after,
                super::transcript_repository::TranscriptPageLimit::default(),
            )?;
            if page.rows.is_empty() {
                return Ok(false);
            }
            for h in page.rows {
                after = Some(h.ordinal);
                let Some(deadline) = h.deadline else {
                    continue;
                };
                let id = EventId::new(h.key.as_slice().try_into().map_err(|_| {
                    crate::eventlog::LogError::CorruptFile("invalid file event key".into())
                })?);
                if self.recipient_metadata_expired(deadline, id, h.wall_clock) {
                    return Ok(true);
                }
            }
        }
    }
    /// The process anchor prevents setting the wall clock backward from extending a deadline.
    pub(in crate::node) fn expiry_now(&self) -> u64 {
        let (start, wall) = self.expiry_clock_start;
        super::node::now_millis().max(wall.saturating_add(start.elapsed().as_millis() as u64))
    pub(in crate::node) fn import_account_backfill(
        &self,
        records: &[BackfillRecord],
    ) -> Result<(), NodeError> {
        self.import_account_backfill_for_account(&self.account_id(), records)
    }

    pub(super) fn import_account_backfill_for_account(
        &self,
        account_id: &str,
        records: &[BackfillRecord],
    ) -> Result<(), NodeError> {
        for r in records {
            let Some(envelope) = DmEnvelope::decode(&r.plaintext) else {
                continue;
            };
            let own = account_id;
            let other = if envelope.route.sender_account == own {
                &envelope.route.recipient_account
            } else if envelope.route.recipient_account == own {
                &envelope.route.sender_account
            } else {
                continue;
            };
            if envelope.route.sender_account != r.from
                || *super::conversation::account_conversation_id(own, other).as_bytes() != r.conv
                || envelope.msg_id != r.event_id
            {
                continue;
            }
            if self.recipient_expired(&envelope.body, EventId::new(r.event_id), r.wall_clock) {
                continue;
            }
            if self.private_dm_message_recalled(other, EventId::new(r.event_id), &r.from)? {
                continue;
            }
            let conversation = ConversationId::new(r.conv);
            if self
                .account_suppression
                .lock()
                .expect("account suppression mutex not poisoned")
                .contains(conversation, EventId::new(envelope.msg_id))?
            {
                continue;
            }
            if self
                .sentlog
                .lock()
                .expect("sent mutex")
                .account_entry(&conversation, envelope.msg_id)?
                .is_some()
            {
                continue;
            }
            let mut received = self.received.lock().expect("received mutex");
            if received
                .account_entry(&conversation, EventId::new(envelope.msg_id))?
                .is_some()
            {
                continue;
            }
            received
                .record_durable(&super::received_log::ReceivedEntry {
                    conversation,
                    from: r.from.clone(),
                    wall_clock: r.wall_clock,
            }
        }
        Ok(uploaded)
    }

    /// Accept inbound connections and maintain deferred profile compactions.
    /// Deferred compactions run on the blocking pool; dropping this future stops
    /// new maintenance scheduling.
    /// CLI and SDK hosts get the same log maintenance as the desktop runtime.
    /// Dropping this future requests listener cancellation; participant retirement
    /// drains its actual child work before stores may be closed or reopened.
    pub async fn run_accept_loop(self: Arc<Self>, listener: TcpListener) {
        Box::pin(self.run_accept_loop_inner(
            listener,
            #[cfg(test)]
            true,
        ))
        .await;
    }

    #[cfg(test)]
    pub(in crate::node) async fn run_accept_loop_without_account_repair(
        self: Arc<Self>,
        listener: TcpListener,
    ) {
        Box::pin(self.run_accept_loop_inner(listener, false)).await;
    }

    /// Direct protocol fixtures retain the bounded production connection owner
    /// while their independent runtime owns retirement. Autonomous host tests
    /// continue to use run_accept_loop and its complete background services.
    #[cfg(test)]
    pub(in crate::node) async fn run_inbound_connections_for_test(
        self: Arc<Self>,
        listener: TcpListener,
    ) {
        self.accept_connections(listener).await;
    }

    async fn run_accept_loop_inner(
        self: Arc<Self>,
        listener: TcpListener,
        #[cfg(test)] account_periodic_repair: bool,
    ) {
        #[cfg(test)]
        let account_history = {
            let node = Arc::clone(&self);
            async move {
                if account_periodic_repair {
                    Box::pin(node.run_account_history_loop()).await;
                } else {
                    Box::pin(node.run_account_history_loop_with_tick(None)).await;
                }
            }
        };
        #[cfg(not(test))]
        let account_history = Arc::clone(&self).run_account_history_loop();
        let changes = self
            .roster
            .lock()
            .expect("roster mutex not poisoned")
            .changes();
        // select! branches share one task. A synchronous maintenance turn must
        // not prevent an available host worker from accepting a new connection.
        // The parent owns cancellation; the actual child owns its retirement
        // permit through destruction of its listener and captured Node.
        let Some(accept_work) = self.runtime_work.admit() else {
            return;
        };
        let mut inbound = tokio::task::JoinSet::new();
        inbound.spawn(accept_work.track(Arc::clone(&self).accept_connections(listener)));
        tokio::select! {
            _ = Arc::clone(&self).run_profile_compaction_loop() => {}
            _ = Arc::clone(&self).run_delivery_loop() => {}
            _ = Arc::clone(&self).run_channel_control_retry_loop() => {}
            _ = Arc::clone(&self).run_channel_recovery_loop(changes) => {}
            _ = account_history => {}
